const supportedLanguages = ['en', 'ru', 'de', 'ua'];
const languageAliases = { uk: 'ua', ua: 'ua', en: 'en', ru: 'ru', de: 'de' };

function browserLanguage() {
  const candidates = navigator.languages?.length ? navigator.languages : [navigator.language];
  for (const value of candidates) {
    const code = value.toLowerCase().split('-')[0];
    if (languageAliases[code]) return languageAliases[code];
  }
  return 'en';
}

function preferredLanguage() {
  const saved = localStorage.getItem('deutscheVerbLanguage');
  return supportedLanguages.includes(saved) ? saved : browserLanguage();
}

function applyLanguage(lang) {
  const dictionary = translations[lang] || translations.en;
  document.documentElement.lang = lang;
  document.querySelectorAll('[data-i18n]').forEach((node) => {
    const key = node.dataset.i18n;
    if (dictionary[key]) node.textContent = dictionary[key];
  });
  document.querySelectorAll('[data-lang]').forEach((button) => {
    button.setAttribute('aria-pressed', String(button.dataset.lang === lang));
  });
}

document.querySelectorAll('[data-lang]').forEach((button) => {
  button.addEventListener('click', () => {
    const lang = button.dataset.lang;
    localStorage.setItem('deutscheVerbLanguage', lang);
    applyLanguage(lang);
    if ('vibrate' in navigator) navigator.vibrate(12);
  });
});

document.querySelectorAll('.haptic').forEach((element) => {
  element.addEventListener('click', () => {
    if ('vibrate' in navigator) navigator.vibrate(10);
  });
});

const observer = new IntersectionObserver((entries) => {
  entries.forEach((entry) => {
    if (entry.isIntersecting) {
      entry.target.classList.add('is-visible');
      observer.unobserve(entry.target);
    }
  });
}, { threshold: 0.16 });

document.querySelectorAll('.reveal').forEach((element) => observer.observe(element));
applyLanguage(preferredLanguage());

if ('serviceWorker' in navigator) {
  window.addEventListener('load', () => {
    navigator.serviceWorker.register('sw.js').catch(() => {});
  });
}
